# ============================================================
# PROJECT FINANCE EXCEL EXPORT
# ============================================================
#
# Purpose:
#   Export the EXACT project-finance inputs and calculations
#   generated by build_project_statement(project)
#
# Input:
#   project
#   analysis
#
# Output:
#   BytesIO Excel workbook
#
# ============================================================

from io import BytesIO
from openpyxl import Workbook
from openpyxl.styles import Font, PatternFill, Border, Side, Alignment
from openpyxl.utils import get_column_letter


# ============================================================
# COLORS / STYLES
# ============================================================

DARK_BLUE = "1F4E78"
BLUE = "D9EAF7"
LIGHT_BLUE = "EAF3F8"
GREY = "D9E1F2"
LIGHT_GREY = "F2F2F2"
GREEN = "E2F0D9"
YELLOW = "FFF2CC"
RED = "FCE4D6"
WHITE = "FFFFFF"
BLACK = "000000"

thin_border = Border(
    left=Side(style="thin", color="BFBFBF"),
    right=Side(style="thin", color="BFBFBF"),
    top=Side(style="thin", color="BFBFBF"),
    bottom=Side(style="thin", color="BFBFBF"),
)


# ============================================================
# BASIC HELPERS
# ============================================================

def safe(value, default=0):
    """
    Convert None to a usable value.
    Keep strings unchanged.
    """
    if value is None:
        return default
    return value


def number(value):
    """
    Numeric Excel value.
    """
    if value is None:
        return 0

    try:
        return float(value)
    except (TypeError, ValueError):
        return value


def fmt_number(cell):
    """
    Excel number formatting.
    """
    cell.number_format = '#,##0.00'


def fmt_percent(cell):
    cell.number_format = '0.00%'


def write_title(ws, row, title_text, end_col=10):
    """
    Writes a section title.
    """

    ws.merge_cells(
        start_row=row,
        start_column=1,
        end_row=row,
        end_column=max(1, end_col)
    )

    cell = ws.cell(row=row, column=1)
    cell.value = title_text

    cell.font = Font(
        bold=True,
        color=WHITE,
        size=12
    )

    cell.fill = PatternFill(
        "solid",
        fgColor=DARK_BLUE
    )

    cell.alignment = Alignment(
        horizontal="left"
    )

    return row


def write_header(ws, row, headers):
    """
    Writes a table header.

    IMPORTANT:
    This function is intentionally called write_header
    instead of header_row to avoid the previous:
        TypeError: 'int' object is not callable
    """

    for col, header in enumerate(headers, start=1):

        cell = ws.cell(
            row=row,
            column=col
        )

        cell.value = header

        cell.font = Font(
            bold=True,
            color=BLACK
        )

        cell.fill = PatternFill(
            "solid",
            fgColor=BLUE
        )

        cell.border = thin_border

        cell.alignment = Alignment(
            horizontal="center",
            vertical="center"
        )

    return row


def write_cell(ws, row, col, value, numeric=False):
    """
    Writes one cell.
    """

    cell = ws.cell(
        row=row,
        column=col
    )

    if numeric:
        cell.value = number(value)
        fmt_number(cell)
    else:
        cell.value = safe(value, "")

    cell.border = thin_border

    return cell


def auto_width(ws, minimum=12, maximum=35):
    """
    Automatically size columns.
    """

    for column_cells in ws.columns:

        length = 0

        column_letter = get_column_letter(
            column_cells[0].column
        )

        for cell in column_cells:

            try:
                value_length = len(
                    str(cell.value)
                )
            except Exception:
                value_length = 0

            length = max(
                length,
                value_length
            )

        ws.column_dimensions[
            column_letter
        ].width = max(
            minimum,
            min(length + 2, maximum)
        )


def freeze(ws, cell="B5"):
    ws.freeze_panes = cell


def style_total_row(ws, row, start_col=1, end_col=None):

    if end_col is None:
        end_col = ws.max_column

    for col in range(start_col, end_col + 1):

        cell = ws.cell(
            row=row,
            column=col
        )

        cell.font = Font(
            bold=True
        )

        cell.fill = PatternFill(
            "solid",
            fgColor=LIGHT_BLUE
        )

        cell.border = thin_border


def add_year_headers(ws, row, project_life):

    headers = ["Particulars"]

    for year in range(1, project_life + 1):
        headers.append(
            f"Year {year}"
        )

    write_header(
        ws,
        row,
        headers
    )

    return row


# ============================================================
# PROJECT SUMMARY
# ============================================================

def build_summary_sheet(wb, project, analysis):

    ws = wb.create_sheet("Project Summary")

    write_title(
        ws,
        1,
        "PROJECT FINANCE SUMMARY",
        4
    )

    rows = [
        ("Project Name", getattr(project, "name", "")),
        ("Project Type", getattr(project, "project_type", "")),
        ("Project Life", getattr(project, "project_life", 0)),
        (
            "Construction Period (Months)",
            getattr(project, "construction_period_months", 0)
        ),
        ("Tax Rate", getattr(project, "tax_rate", 0)),
        ("Interest Rate", getattr(project, "interest_rate", 0)),
        ("Loan Tenor", getattr(project, "loan_tenor", 0)),
        (
            "Repayment Frequency",
            getattr(project, "repayment_frequency", "")
        ),
        (
            "Repayment Type",
            getattr(project, "repayment_type", "")
        ),
        (
            "Moratorium (Months)",
            getattr(project, "moratorium_months", 0)
        ),
        (
            "Interest Capitalized",
            getattr(project, "interest_capitalized", False)
        ),
    ]

    row = 3

    for label, value in rows:

        ws.cell(row=row, column=1).value = label
        ws.cell(row=row, column=1).font = Font(bold=True)

        ws.cell(row=row, column=2).value = value

        ws.cell(row=row, column=1).border = thin_border
        ws.cell(row=row, column=2).border = thin_border

        row += 1

    # --------------------------------------------------------
    # Analysis summary
    # --------------------------------------------------------

    projection = analysis.get(
        "projection",
        []
    )

    row += 2

    write_title(
        ws,
        row,
        "KEY PROJECT OUTPUTS",
        4
    )

    row += 2

    headers = [
        "Metric",
        "Year 1",
        "Year 2",
        "Year 3",
        "Project Life"
    ]

    write_header(
        ws,
        row,
        headers
    )

    metrics = [
        ("Revenue", "revenue"),
        ("EBITDA", "ebitda"),
        ("EBIT", "ebit"),
        ("EBT", "ebt"),
        ("PAT", "pat"),
        ("Cash Flow from Operations", "cashflow_operations"),
        ("Cash Flow from Investing", "cashflow_investing"),
        ("Cash Flow from Financing", "cashflow_financing"),
        ("Closing Cash", "closing_cash"),
        ("Closing Debt", "closing_debt"),
        ("Total Assets", "total_assets"),
        ("Total Liabilities", "total_liabilities"),
        ("Total Equity", "total_equity"),
        ("Balance Sheet Gap", "balance_sheet_gap"),
    ]

    row += 1

    for label, key in metrics:

        ws.cell(row=row, column=1).value = label

        for col in range(2, 5):

            index = col - 2

            if index < len(projection):

                value = projection[index].get(
                    key,
                    0
                )

            else:
                value = 0

            cell = ws.cell(
                row=row,
                column=col
            )

            cell.value = number(value)
            fmt_number(cell)

        # Project-life / final-year value

        if projection:

            value = projection[-1].get(
                key,
                0
            )

        else:
            value = 0

        cell = ws.cell(
            row=row,
            column=5
        )

        cell.value = number(value)
        fmt_number(cell)

        row += 1

    auto_width(ws)

    freeze(ws, "B3")

    return ws


# ============================================================
# REVENUE ASSUMPTIONS
# ============================================================

def build_revenue_assumptions_sheet(
    wb,
    project
):

    ws = wb.create_sheet(
        "Revenue Assumptions"
    )

    write_title(
        ws,
        1,
        "REVENUE ASSUMPTIONS",
        17
    )

    headers = [
        "Name",
        "Type",
        "Amount",
        "Growth",
        "Capacity MW",
        "Operating Hours",
        "CUF",
        "Tariff",
        "Tariff Escalation",
        "Degradation",
        "Rooms",
        "Occupancy %",
        "ADR",
        "Food %",
        "Banquet %",
        "Spa %",
        "Other %"
    ]

    write_header(
        ws,
        3,
        headers
    )

    row = 4

    for item in getattr(
        project,
        "revenue_items",
        []
    ):

        values = [
            getattr(item, "name", ""),
            getattr(item, "revenue_type", ""),
            getattr(item, "amount", 0),
            getattr(item, "growth_rate", 0),
            getattr(item, "capacity_mw", 0),
            getattr(item, "operating_hours", 0),
            getattr(item, "cuf", 0),
            getattr(item, "tariff", 0),
            getattr(item, "tariff_escalation", 0),
            getattr(item, "degradation_rate", 0),
            getattr(item, "rooms", 0),
            getattr(item, "occupancy_pct", 0),
            getattr(item, "adr", 0),
            getattr(item, "food_revenue_pct", 0),
            getattr(item, "banquet_revenue_pct", 0),
            getattr(item, "spa_revenue_pct", 0),
            getattr(item, "other_revenue_pct", 0),
        ]

        for col, value in enumerate(
            values,
            start=1
        ):

            cell = ws.cell(
                row=row,
                column=col
            )

            if col == 1 or col == 2:
                cell.value = safe(
                    value,
                    ""
                )
            else:
                cell.value = number(value)
                fmt_number(cell)

            cell.border = thin_border

        row += 1

    if row == 4:
        ws.cell(
            row=row,
            column=1
        ).value = "No revenue assumptions found."

    auto_width(ws)

    freeze(ws, "A4")

    return ws


