# ============================================================
# DEBT ASSUMPTIONS
# ============================================================

def build_debt_assumptions_sheet(
    wb,
    project
):

    ws = wb.create_sheet(
        "Debt Assumptions"
    )

    write_title(
        ws,
        1,
        "DEBT ASSUMPTIONS",
        5
    )

    headers = [
        "Drawdown Year",
        "Drawdown Month",
        "Drawdown Amount",
        "Repayment Frequency",
        "Repayment Type"
    ]

    write_header(
        ws,
        3,
        headers
    )

    row = 4

    for item in getattr(
        project,
        "debt_drawdowns",
        []
    ):

        values = [
            getattr(item, "year", 0),
            getattr(item, "drawdown_months", 0),
            getattr(item, "drawdown_amount", 0),
            getattr(
                project,
                "repayment_frequency",
                ""
            ),
            getattr(
                project,
                "repayment_type",
                ""
            )
        ]

        for col, value in enumerate(
            values,
            start=1
        ):

            cell = ws.cell(
                row=row,
                column=col
            )

            if col >= 3 and col != 4 and col != 5:
                cell.value = number(value)
                fmt_number(cell)
            else:
                cell.value = safe(
                    value,
                    ""
                )

            cell.border = thin_border

        row += 1

    # Project-level debt information

    row += 2

    write_title(
        ws,
        row,
        "DEBT PARAMETERS",
        3
    )

    row += 2

    debt_params = [
        ("Interest Rate", getattr(project, "interest_rate", 0)),
        ("Loan Tenor", getattr(project, "loan_tenor", 0)),
        ("Moratorium Months", getattr(project, "moratorium_months", 0)),
        (
            "Interest Capitalized",
            getattr(project, "interest_capitalized", False)
        ),
    ]

    for label, value in debt_params:

        ws.cell(
            row=row,
            column=1
        ).value = label

        ws.cell(
            row=row,
            column=1
        ).font = Font(bold=True)

        ws.cell(
            row=row,
            column=2
        ).value = value

        ws.cell(
            row=row,
            column=1
        ).border = thin_border

        ws.cell(
            row=row,
            column=2
        ).border = thin_border

        if isinstance(value, (int, float)):

            fmt_number(
                ws.cell(
                    row=row,
                    column=2
                )
            )

        row += 1

    auto_width(ws)

    return ws


