# ============================================================
# REVENUE DETAIL
# ============================================================

def build_revenue_detail_sheet(
    wb,
    analysis,
    project
):

    ws = wb.create_sheet(
        "Revenue Detail"
    )

    projection = analysis.get(
        "projection",
        []
    )

    project_life = getattr(
        project,
        "project_life",
        len(projection)
    )

    write_title(
        ws,
        1,
        "REVENUE DETAIL",
        project_life + 5
    )

    headers = [
        "Revenue Item",
        "Type",
        "Metric"
    ]

    for year in range(
        1,
        project_life + 1
    ):
        headers.append(
            f"Year {year}"
        )

    write_header(
        ws,
        3,
        headers
    )

    # Gather every revenue item / metric appearing
    # in the backend result.

    detail_map = {}

    for year_index, p in enumerate(
        projection
    ):

        year = year_index + 1

        breakdown = p.get(
            "revenue_breakdown",
            {}
        )

        for item_name, data in breakdown.items():

            item_type = data.get(
                "type",
                ""
            )

            if item_name not in detail_map:
                detail_map[item_name] = {
                    "type": item_type,
                    "metrics": set()
                }

            for metric in data.keys():

                if metric != "type":

                    detail_map[
                        item_name
                    ]["metrics"].add(metric)

    row = 4

    for item_name, item_data in detail_map.items():

        item_type = item_data["type"]

        for metric in sorted(
            item_data["metrics"]
        ):

            ws.cell(
                row=row,
                column=1
            ).value = item_name

            ws.cell(
                row=row,
                column=2
            ).value = item_type

            ws.cell(
                row=row,
                column=3
            ).value = metric

            for year_index in range(
                project_life
            ):

                value = 0

                if year_index < len(projection):

                    breakdown = projection[
                        year_index
                    ].get(
                        "revenue_breakdown",
                        {}
                    )

                    data = breakdown.get(
                        item_name,
                        {}
                    )

                    value = data.get(
                        metric,
                        0
                    )

                cell = ws.cell(
                    row=row,
                    column=year_index + 4
                )

                cell.value = number(value)

                fmt_number(cell)

                cell.border = thin_border

            for col in range(1, 4):
                ws.cell(
                    row=row,
                    column=col
                ).border = thin_border

            row += 1

    auto_width(ws)

    return ws


